function iconSVG(key){
 const paths=ICON_PATHS[key]||ICON_PATHS['🌟'];
 const [bg,ink,accent]=ICON_COLOR_PAIRS[key]||ICON_COLOR_PAIRS['🌟'];
 return `<svg class="vector-icon" viewBox="0 0 48 48" aria-hidden="true" xmlns="http://www.w3.org/2000/svg">
 <rect x="2" y="2" width="44" height="44" rx="15" fill="${bg}"/>
 <circle cx="38" cy="11" r="6" fill="${accent}" opacity=".85"/>
 <circle cx="10" cy="37" r="4" fill="${accent}" opacity=".55"/>
 <g transform="translate(8 8) scale(1.333333)" fill="none" stroke="${ink}" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round">${paths}</g></svg>`;
}
