let state={view:'home',detail:null,profilePhoto:null,phase:'dev'};
try {const stored=JSON.parse(localStorage.getItem(STORE)||'null');if(stored&&typeof stored==='object'&&typeof stored.profilePhoto==='string')state.profilePhoto=stored.profilePhoto;}catch{}
function save(){try{localStorage.setItem(STORE,JSON.stringify({profilePhoto:state.profilePhoto,phase:'dev'}));return true}catch{return false}}
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&quot;',"'":'&#39;'}[c]));
const avatar=()=>state.profilePhoto?`<img alt="Raesya profile" src="${safe(state.profilePhoto)}">` :iconSVG('🌸');
// Copies only Raesya's photo after the user chooses to import. NEVER changes V14.
function importPhotoFromV14(){
 const message=msg=>{const el=$('photoStatus');if(el)el.textContent=msg;else alert(msg)};
 try{
  const raw=localStorage.getItem('my-daily-routine-v2')||localStorage.getItem('my-daily-routine-v1');
  if(!raw){message('V14 photo was not found in this browser. Choose Photo instead, or restore your V14 backup on the original V14 app.');return}
  const old=JSON.parse(raw),children=Array.isArray(old.children)?old.children:[];
  const child=children.find(k=>String(k.name||'').trim().toLowerCase()==='raesya')||children.find(k=>String(k.name||'').toLowerCase().includes('raesya'));
  const photo=child?.photo;
  if(typeof photo!=='string'||!/^data:image\/(png|jpeg|webp);base64,/i.test(photo)){message('No saved Raesya picture was found in V14. Please choose a photo manually.');return}
  const previous=state.profilePhoto;state.profilePhoto=photo;
  if(!save()){state.profilePhoto=previous;message('Storage full. Please choose a smaller photo.');return}
  render();
 }catch(e){message('Could not read V14 photo. Please use Choose Photo instead.')}
}
async function loadProfilePhoto(file){
 const status=$('photoStatus');
 const notify=s=>{if(status)status.textContent=s;else alert(s)};
 if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){notify('Choose a JPG, PNG or WebP image smaller than 8 MB.');return}
 try{
  const raw=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});
  const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=raw});
  const canvas=document.createElement('canvas'),size=420;canvas.width=canvas.height=size;
  const ctx=canvas.getContext('2d'),edge=Math.min(img.width,img.height),x=(img.width-edge)/2,y=(img.height-edge)/2;
  ctx.drawImage(img,x,y,edge,edge,0,0,size,size);
  const photo=canvas.toDataURL('image/jpeg',.82),previous=state.profilePhoto;state.profilePhoto=photo;
  if(!save()){state.profilePhoto=previous;notify('Storage full. Unable to save photo.');return}
  render();
 }catch(e){notify('Picture could not be read. Choose a different photo.')}
}
function setMenu(open){$('sidebar').classList.toggle('open',open);$('sidebar').setAttribute('aria-hidden',String(!open));$('veil').hidden=!open;$('openMenu').setAttribute('aria-expanded',String(open));document.body.classList.toggle('menu-open',open);if(open)$('closeMenu').focus();}
function goto(id){if(!MENU.some(m=>m.id===id))return;state.view=id;state.detail=null;setMenu(false);render();$('view').focus({preventScroll:true});window.scrollTo(0,0)}
function home(){state.detail=null;state.view='home';setMenu(false);render();window.scrollTo(0,0)}
// Approved navigation: Back always returns to the main dashboard.
function back(){home()}
function moduleCard(id){const m=MENU.find(x=>x.id===id);return `<button class="card" style="--bg:${m.bg};--fg:${m.fg}" data-go="${id}"><span class="emoji">${iconSVG(m.emoji)}</span><strong>${m.name}</strong><small>${id==='revision'?'Learn & Practice':id==='quiz'?'Test Your Skills':id==='games'?'Play & Learn':'Draw & Color'}</small></button>`}
function hub(m){
 const mod=MODULES[state.view];
 const cards=mod.items.map((item,i)=>`<button class="activity-card" data-detail="${item.id}" style="--tile:${item.tone};--item-accent:${mod.ink}"><span class="activity-art" aria-hidden="true"><span class="art-dot dot-a"></span><span class="art-dot dot-b"></span><span class="activity-emoji">${iconSVG(item.icon)}</span></span><span class="activity-info"><span class="activity-label">${safe(item.label)}</span><strong>${safe(item.name)}</strong><small>${safe(item.desc)}</small><span class="activity-open">Explore <span aria-hidden="true">→</span></span></span></button>`).join('');
 return `<section class="panel app-screen module-shell" style="--module-tint:${mod.accent};--module-ink:${mod.ink}">${head(m)}${state.view==='rizqi'?`<div class="rizqi-header"><picture><source media="(max-width: 600px)" srcset="${RIZQI_HEADER_MOBILE}"><img src="${RIZQI_HEADER_DESKTOP}" alt="Rizqi as a cheerful cartoon safari explorer with friendly jungle animals and the words Rizqi Explorer" loading="eager"></picture><div class="rizqi-mobile-title"><h2>Rizqi Explorer</h2><p>Learn, play and explore!</p></div></div>`:`<div class="module-hero"><span class="module-hero-art" aria-hidden="true">${iconSVG(mod.icon)}</span><div><span class="eyebrow">${safe(mod.tag)}</span><h2>${safe(m.name)}</h2><p>${safe(mod.intro)}</p></div></div>`}<div class="section-title"><div><h3>Choose your adventure</h3><p>Tap a card to explore</p></div><span class="preview-tag">UI Preview</span></div><div class="activity-grid">${cards}</div><div class="module-footnote">Beautiful things are coming! These cards preview the V15 activities. Learning lessons and games are not available yet.</div></section>`;
}
function head(m){return `<div class="modulehead"><button class="backbtn" data-back>← Back to Home</button><h1>${iconSVG(m.emoji)} ${safe(m.name)}</h1><button class="backbtn" data-home>⌂ Home</button></div>`}
function detailView(m){
 if(state.view==='revision')return revisionScreen(m);
 const mod=MODULES[state.view],item=mod.items.find(x=>x.id===state.detail);
 if(!item){state.detail=null;return hub(m)}
 return `<section class="panel app-screen module-shell" style="--module-tint:${mod.accent};--module-ink:${mod.ink}">${head(m)}<div class="detail-intro" style="--tile:${item.tone}"><div class="detail-bigicon">${iconSVG(item.icon)}</div><span class="activity-label">${safe(item.label)}</span><h2>${safe(item.name)}</h2><p>${safe(item.desc)}</p><span class="status-pill">In development</span></div><div class="detail-bottom"><h3>Coming in a later development phase</h3><p>This is the design preview for ${safe(item.name)}. Its learning content or interactive game has not been implemented or tested yet.</p><button class="action primary" data-module>← All ${safe(m.name)} activities</button></div></section>`;
}
function render(){const m=MENU.find(x=>x.id===state.view);$('sidebarAvatar').innerHTML=avatar();$('menuList').innerHTML=MENU.map(x=>`<button class="menu-button ${x.id===state.view?'active':''}" data-id="${x.id}" style="--bg:${x.bg};--fg:${x.fg}"><span>${iconSVG(x.emoji)}</span>${x.name}</button>`).join('');
if(state.view==='home'){$('view').innerHTML=`<div class="app-screen"><section class="home-banner" aria-label="Raesya's WonderLand main header"><img src="data:image/webp;base64," alt="Raesya's WonderLand — Learn, Play, Shine!" loading="eager" decoding="async"></section>${!state.profilePhoto?`<section class="panel photo-onboarding"><strong>📷 Add Raesya’s profile picture (sidebar)</strong><p>Use the picture saved in V14, or choose one from this device.</p><div class="photo-actions"><button class="action primary" data-import-v14>Use Photo from V14</button><label class="action file-picker">Choose Photo<input type="file" id="homePhotoInput" accept="image/png,image/jpeg,image/webp" hidden></label></div><p id="photoStatus" role="status" class="photo-status"></p></section>`:""}<h2>Explore Your Wonderland</h2><div class="cards">${['revision','quiz','games','art'].map(moduleCard).join('')}</div><section class="panel"><button class="banner" data-go="rizqi">${iconSVG("🧸")} Rizqi Explorer →<br><small>Little adventures for Rizqi!</small></button></section><p class="notice">V15 development preview. Learning content is not installed yet.</p></div>`;return}
if(state.view==='settings'){$('view').innerHTML=`<section class="panel app-screen">${head(m)}<div class="setting-box"><h2>Development profile</h2><p class="muted">Add a local Raesya photo, or use the button on Home to copy it from V14 (read-only). V14 will never be changed.</p><label>Choose image (PNG/JPEG/WebP; maximum 8 MB)<input id="photoInput" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="inlineactions"><button class="action" data-remove-photo>Remove preview photo</button></div><p class="statline">This photo is stored locally in this browser only. Do not upload a private backup JSON to a public repository.</p><p id="photoStatus" role="status"></p></div></section>`;return}
if(state.view==='parent'){$('view').innerHTML=`<section class="panel app-screen">${head(m)}<div class="placeholder"><h2>Protected section not yet available</h2><p class="muted">Parent PIN, academic reports, Rizqi controls, and safe Restore will be implemented and tested in their dedicated phase. No PIN or private learning records are accessible in this preview.</p></div></section>`;return}
$('view').innerHTML=state.detail?detailView(m):hub(m);
}
$('menuList').addEventListener('click',e=>{const b=e.target.closest('button[data-id]');if(b)goto(b.dataset.id)});
$('view').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.go)goto(b.dataset.go);else if(b.dataset.detail){state.detail=b.dataset.detail;if(state.view==='revision')resetRevisionSelection();render();window.scrollTo(0,0)}else if(b.hasAttribute('data-module')){state.detail=null;render()}else if(b.hasAttribute('data-back'))back();else if(b.hasAttribute('data-home'))home();else if(b.hasAttribute('data-import-v14'))importPhotoFromV14();else if(b.hasAttribute('data-remove-photo')){state.profilePhoto=null;save();render()}});
$('view').addEventListener('click',handleRevisionClick);
$('view').addEventListener('change',e=>{if(e.target.id!=='photoInput'&&e.target.id!=='homePhotoInput')return;loadProfilePhoto(e.target.files?.[0]);});
$('openMenu').addEventListener('click',()=>setMenu(true));$('closeMenu').addEventListener('click',()=>setMenu(false));$('veil').addEventListener('click',()=>setMenu(false));window.addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false)});
render();
